import java.util.Scanner;

public class Main {
    static long[][] dp;
    static int n, h;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        h = sc.nextInt();

        dp = new long[n + 1][n + 1];

        // Initialize dp with -1 to indicate uncomputed states
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                if (i == 0 && j == 0) {
                    dp[i][j] = 1;
                } else {
                    dp[i][j] = -1;
                }
            }
        }

        // Compute all states
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                t(i, j);
            }
        }

        long result = 0;
        for (int i = h; i <= n; i++) {
            result += dp[n][i];
        }
        System.out.println(result);
        sc.close();
    }

    static long t(int n, int h) {
        if (dp[n][h] != -1) {
            return dp[n][h];
        }
        long result = 0;
        for (int m = 1; m <= n; m++) {
            long sum1 = 0;
            for (int i = 0; i < h; i++) {
                sum1 += t(n - m, i);
            }
            long sum2 = 0;
            for (int i = 0; i < h - 1; i++) {
                sum2 += t(m - 1, i);
            }
            result += t(m - 1, h - 1) * sum1 + t(n - m, h - 1) * sum2;
        }
        dp[n][h] = result;
        return result;
    }
}
